	"identity_education_conditions": "XとAu10tixが、私の身分証明書と自撮りの画像（抽出された生体データを含む）を、身元確認やXの関連する安全とセキュリティ（なりすましの防止を含む）の目的で使用することに同意します。Au10tixは、そのデータを最大30日間保存することがあります。{{}}詳細はこちら{{}}",
