	"identity_education_conditions_eea": "\"Xが私の身分証明書の画像（生体データを含む）とプロフィールの個人データを、身元確認の目的でAu10tixと共有することに同意します。\nさらに、Xが私の身分証明書の画像（生体データを含む）を最大30日間保存し、その画像およびプロフィールのデータを安全とセキュリティ（なりすましの防止を含む）の目的で利用することにも同意します。{{}}詳細はこちら{{}}\"",
	"identity_education_conditions_persona_vendor": "私の身分証明書と自撮りの画像（抽出された生体データを含む）を、身元確認やXに関連する安全とセキュリティ、なりすまし防止、支払い目的で、XとPersonaが使用することに同意します。Personaは、そのデータを最大30日間保存することがあります。Xは、私がXプレミアムサービスをサブスクライブしている限り、氏名、住所、ハッシュ化された公的な身分証明書番号を保存することがあります。{{}}詳細はこちら{{}}",
