	"payment_funds_insurance_footer_secondary_text": "FDICの保険と口座所有権のカテゴリーの詳細については、﻿こちら﻿をご覧ください。",
	"payment_funds_insurance_footer_text": "お客様の預金はFDIC（連邦預金保険公社）の会員であるCross River Bankにて保管され、FDICによって保護されます。保護の対象となるのは、当該銀行における各口座所有区分のすべての口座（合算）に対し、個人および法人それぞれ最大25万米ドルまでです。これには、代理名義で所有されている口座も含まれます。",
	"payment_funds_insurance_footer_text_format": "お客様の預金はFDIC（連邦預金保険公社）加盟機関のCross River Bank（「銀行」）にて保管され、FDICによって保護されます。保護の対象となるのは、当該銀行における各口座所有区分のすべての口座（合算）に対し、個人および法人それぞれ最大{amount}までです。これには、代理人名義で所有されている口座も含まれます。",
	"payment_funds_insurance_sweep_disclaimer": "預金は、FDIC加盟のCross River Bankおよびその他の﻿FDIC保険対象金融機関﻿で保管されます。パススルー預金保険の適用には、﻿所定の条件﻿を満たす必要があります。X Payments LLCはFDICによる預金保険の対象となる銀行ではありません。預金保険は、保険対象となっている銀行が破綻した場合にのみ適用されます。",
	"payment_funds_insurance_sweep_presentation": "預金は自動的にX Cash Sweepプログラムに登録されます。これにより、一定の制限のもと、最大1,000万ドルのFDIC保険が適用されます。﻿詳細はこちら﻿。",
