	"ps__tip_broadcaster_1": "<b>ヒント:</b> ライブ放送のご利用ありがとうございます。参加者があれば、忘れずにあいさつするようにしましょう。",
	"ps__tip_broadcaster_11": "<b>ヒント:</b> Periscopeライブ放送のご利用ありがとうございます。 U+227A",
	"ps__tip_broadcaster_2": "<b>ヒント:</b> 参加した視聴者を名前で呼びかけてみましょう。感激してくれるはずです。",
	"ps__tip_broadcaster_3": "<b>ヒント:</b> 視聴者に見つけてもらいやすくするため、ライブ放送は数分以上行うようにしてください。",
	"ps__tip_broadcaster_4": "<b>ヒント:</b> どこから見ているかを視聴者にたずねると、会話のきっかけになります。",
	"ps__tip_broadcaster_5": "<b>ヒント:</b> 視聴者を引き付け続けられるよう、視聴に感謝してコメントにも反応しましょう。",
	"ps__tip_broadcaster_6": "<b>ヒント:</b> ライブ放送中に接続が途切れた場合、電波が届く場所に移動しましょう。",
	"ps__tip_broadcaster_7": "<b>ヒント:</b> 視聴者にフォローを呼びかけ、ライブ放送時の通知を受け取ってもらえるようにしましょう。",
	"ps__tip_broadcaster_8": "<b>ヒント:</b> ライブ放送はあいさつから始めましょう。リピーターが喜びます。",
	"ps__tip_broadcaster_9": "<b>ヒント:</b> ライブ放送を終了する前に視聴者に感謝を伝えましょう。",
	"ps__tip_pre_broadcast_1": "<b>ヒント:</b> ライブ放送を始める前にタイトルを作成し、同じような興味関心を持つ視聴者とつながりましょう。",
	"ps__tip_pre_broadcast_2": "<b>ヒント:</b> 適切なタイトルを付けると、ライブ放送の内容がわかりやすくなります。",
	"ps__tip_pre_broadcast_3": "<b>ヒント:</b> たとえば、場所を案内したり、才能を披露したり、関心事について話したりしましょう。",
	"ps__tip_pre_broadcast_4": "<b>ヒント:</b> ライブ放送を始める前に電波強度が十分か確認してください。",
	"ps__tip_pre_broadcast_5": "<b>ヒント:</b> 視聴者を増やせるよう、ライブ放送をXで共有しましょう。",
	"ps__tip_pre_broadcast_6": "<b>ヒント:</b> 相互フォロー者向けに限定公開でライブ放送できます。",
	"ps__tip_pre_broadcast_8": "<b>ヒント:</b> ライブ放送を見つけてもらいやすくするため、タイトルに関連するハッシュタグを追加しましょう。",
	"ps__tip_pre_broadcast_9": "<b>ヒント:</b> ヒントは以上です。Periscopeのご利用ありがとうございます。",
	"ps__tip_viewer_1": "<b>ヒント:</b> 最初の参加者として、コメントを書いてあいさつしましょう。",
